/**
 * Tiny FICTIONAL test images (blue and white checkerboards, generated with an
 * image encoder for these tests). Real encoder output, so the content checks
 * are tested against genuine files rather than hand-made headers.
 */

export function bytes(base64: string): Uint8Array {
  return new Uint8Array(Buffer.from(base64, "base64"));
}

